import{_ as o,C as s,o as e,c as d,a3 as r,j as i,E as l,a as n}from"./chunks/framework.C6R8kWFE.js";const I=JSON.parse('{"title":"2-dars (Mentor). Android tizimi va uning arxitekturasi","description":"","frontmatter":{"title":"2-dars (Mentor). Android tizimi va uning arxitekturasi","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Android)","link":"/mentor/9-sinf-android/"},"week":{"n":1,"link":"/mentor/9-sinf-android/hafta-01/"},"g":2,"title":"Android tizimi va uning arxitekturasi","lead":"Android tizimi va arxitekturasi: Linux Kernel, HAL, ART/Dalvik, kutubxonalar va Java API Framework","slide":"/slaydlar/9-sinf-android/hafta-01/dars-2.html","test":"/slaydlar/9-sinf-android/hafta-01/dars-2-test.html","student_link":"/9-sinf-android/hafta-01/dars-2","tabs":[{"g":1,"link":"/mentor/9-sinf-android/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/9-sinf-android/hafta-01/dars-2","current":true},{"g":3,"link":"/mentor/9-sinf-android/hafta-01/dars-3","current":false}],"prev":{"g":1,"title":"Android nima va uning rivojlanish tarixi","link":"/mentor/9-sinf-android/hafta-01/dars-1"},"next":{"g":3,"title":"Androidning imkoniyatlari va qo‘llanilish sohalari","link":"/mentor/9-sinf-android/hafta-01/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-android/hafta-01/dars-2.md","filePath":"mentor/9-sinf-android/hafta-01/dars-2.md"}'),m={name:"mentor/9-sinf-android/hafta-01/dars-2.md"},u={class:"blk"},h={id:"_1-dars-maqsadi-va-kutiladigan-natijalar",tabindex:"-1"},g={class:"blk"},v={id:"_2-dars-rejasi-80-daqiqa",tabindex:"-1"},q={class:"blk"},k={id:"_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt",tabindex:"-1"},y={class:"blk"},p={id:"_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari",tabindex:"-1"},b={class:"blk"},c={id:"_5-tezkor-savol-javob-blits-savollar",tabindex:"-1"},x={class:"blk"},f={id:"_6-mentor-uchun-amaliy-tavsiyalar",tabindex:"-1"};function A(_,a,z,T,P,L){const t=s("Icon");return e(),d("div",null,[a[18]||(a[18]=r("<p><strong>Sinf:</strong> 9-sinf (Android dasturlash)<br><strong>Hafta:</strong> 1-hafta<br><strong>Dars tartibi:</strong> 2-dars (umumiy 102 darsdan 2-darsi)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Format:</strong> Nazariy va tizimli tahlil mashg&#39;uloti</p><hr>",2)),i("div",u,[i("h2",h,[l(t,{name:"file-text"}),a[0]||(a[0]=n(" 1. Dars maqsadi va kutiladigan natijalar ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-maqsadi-va-kutiladigan-natijalar","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars maqsadi va kutiladigan natijalar"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Maqsad:</strong> O&#39;quvchilarga Android operatsion tizimining ko&#39;p qatlamli vertikal arxitekturasi (Linux Kernel, HAL, Native Libraries, Android Runtime, Java API Framework, Applications) hamda tizimda ma&#39;lumotlarni saqlash mexanizmlari (SQLite, Room, SharedPreferences, Firebase) haqida chuqur bilim berish.</li><li><strong>Kutiladigan natijalar:</strong><ul><li>O&#39;quvchi Android arxitekturasining 5 ta asosiy qatlamini tartib bilan biladi va har bir qatlamning vazifasini tushuntira oladi;</li><li>Linux Kernel va Hardware Abstraction Layer (HAL) ning apparat ta&#39;minoti bilan aloqasini tushunadi;</li><li>Dalvik Virtual Machine (DVM) va Android Runtime (ART) o&#39;rtasidagi farqni (JIT vs AOT kompilyatsiya) anglaydi;</li><li>Java API Framework tarkibidagi asosiy menejerlarni (Activity Manager, Notification Manager, Content Provider, View System) ajrata oladi;</li><li>Nima uchun har bir Android ilovasi alohida jarayonda (Process) va alohida foydalanuvchi (UID) sifatida ishga tushishini xavfsizlik nuqtai nazaridan asoslay oladi;</li><li>Androidda ma&#39;lumot saqlash texnologiyalari (SharedPreferences, SQLite, Room, Firebase) farqini biladi.</li></ul></li></ul><hr>",2))]),i("div",g,[i("h2",v,[l(t,{name:"file-text"}),a[3]||(a[3]=n(" 2. Dars rejasi (80 daqiqa) ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars rejasi (80 daqiqa)"'},"​",-1))]),a[5]||(a[5]=r('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Tavsif</th></tr></thead><tbody><tr><td><strong>00–10 daq</strong></td><td>O&#39;tgan mavzuni takrorlash va kirish</td><td>Andy Rubin, Google xaridi, HTC Dream, Android versiyalari bo&#39;yicha blits-savol. Muammoli savol: &quot;Ilova kodimiz qanday qilib telefon kamerasini ishlatadi?&quot;</td></tr><tr><td><strong>10–35 daq</strong></td><td>Yangi mavzu: Qatlamli arxitektura</td><td>Linux Kernel, HAL, Native C/C++ kutubxonalari, Android Runtime (Dalvik vs ART), Java baytkodi va <code>.dex</code> fayllar</td></tr><tr><td><strong>35–55 daq</strong></td><td>Yangi mavzu: Framework va ilovalar</td><td>Java API Framework (Activity Manager, View System va boshqalar), Ilovalar qatlami, jarayonlar izolyatsiyasi (Sandbox)</td></tr><tr><td><strong>55–65 daq</strong></td><td>Ma&#39;lumotlarni saqlash texnologiyalari</td><td>SharedPreferences, Room / SQLite, Firebase Realtime Database va Cloud Firestore</td></tr><tr><td><strong>65–75 daq</strong></td><td>Amaliy mashq va sxematik tahlil</td><td>Android arxitektura sxemasini daftarga chizish va tarkibiy elementlarni to&#39;g&#39;ri joylashtirish</td></tr><tr><td><strong>75–80 daq</strong></td><td>Xulosa va baholash</td><td>Dars yakunlari, o&#39;quvchilarni baholash, uyga vazifa topshirish</td></tr></tbody></table><hr>',2))]),i("div",q,[i("h2",k,[l(t,{name:"file-text"}),a[6]||(a[6]=n(" 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt) ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt","aria-label":`Permalink to "<Icon name="file-text" /> 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt)"`},"​",-1))]),a[8]||(a[8]=r(`<h3 id="_3-1-android-arxitekturasining-vertikal-qatlamlari" tabindex="-1">3.1. Android arxitekturasining vertikal qatlamlari <a class="header-anchor" href="#_3-1-android-arxitekturasining-vertikal-qatlamlari" aria-label="Permalink to &quot;3.1. Android arxitekturasining vertikal qatlamlari&quot;">​</a></h3><p>Android operatsion tizimi modulli, ko&#39;p qatlamli (stack) arxitekturaga ega. Har bir qatlam faqat o&#39;zidan pastdagi qatlam xizmatlaridan foydalanadi va yuqoridagi qatlamga tayyor interfeys taqdim etadi:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>+-------------------------------------------------------+</span></span>
<span class="line"><span>| 5. Applications (Ilovalar qatlami)                   |</span></span>
<span class="line"><span>|    System Apps (Phone, Contacts) + User Apps (Click)   |</span></span>
<span class="line"><span>+-------------------------------------------------------+</span></span>
<span class="line"><span>| 4. Java API Framework (Tizim karkasi)                |</span></span>
<span class="line"><span>|    Activity Manager, View System, Content Providers... |</span></span>
<span class="line"><span>+-------------------------------------------------------+</span></span>
<span class="line"><span>| 3. Android Runtime (ART)   | Native C/C++ Libraries   |</span></span>
<span class="line"><span>|    DEX bytecode, AOT / JIT | SQLite, WebKit, Media    |</span></span>
<span class="line"><span>+-------------------------------------------------------+</span></span>
<span class="line"><span>| 2. Hardware Abstraction Layer (HAL)                   |</span></span>
<span class="line"><span>|    Kamera, Audio, Bluetooth, Datchiklar interfeysi   |</span></span>
<span class="line"><span>+-------------------------------------------------------+</span></span>
<span class="line"><span>| 1. Linux Kernel (Linux yadrosi)                       |</span></span>
<span class="line"><span>|    Drayverlar, Xotira, Jarayonlar, Quvvat boshqaruvi  |</span></span>
<span class="line"><span>+-------------------------------------------------------+</span></span></code></pre></div><h3 id="_3-2-1-qatlam-linux-kernel-linux-yadrosi" tabindex="-1">3.2. 1-qatlam: Linux Kernel (Linux yadrosi) <a class="header-anchor" href="#_3-2-1-qatlam-linux-kernel-linux-yadrosi" aria-label="Permalink to &quot;3.2. 1-qatlam: Linux Kernel (Linux yadrosi)&quot;">​</a></h3><p>Android to&#39;liq Linux operatsion tizimi emas, lekin uning yadrosi (Linux Kernel 5.x / 6.x) ustiga qurilgan. Linux yadrosining asosiy vazifalari:</p><ul><li><strong>Drayverlar boshqaruvi:</strong> Kamera (Camera Driver), displey, klaviatura, Bluetooth, Wi-Fi, audio drayverlari;</li><li><strong>Xotira va resurslar:</strong> Virtual xotira (RAM) boshqaruvi, Low Memory Killer (RAM tugaganda keraksiz ilovalarni yopish);</li><li><strong>Jarayonlar nazorati (Process Management):</strong> CPU vaqtini ilovalar o&#39;rtasida rejalashtirish;</li><li><strong>Xavfsizlik modeli:</strong> Linux foydalanuvchilari tizimi (har bir o&#39;rnatilgan ilovaga alohida <code>app_xxxx</code> UID beriladi).</li></ul><h3 id="_3-3-2-qatlam-hardware-abstraction-layer-hal" tabindex="-1">3.3. 2-qatlam: Hardware Abstraction Layer (HAL) <a class="header-anchor" href="#_3-3-2-qatlam-hardware-abstraction-layer-hal" aria-label="Permalink to &quot;3.3. 2-qatlam: Hardware Abstraction Layer (HAL)&quot;">​</a></h3><p>Har xil smartfonlarda har xil ishlab chiqaruvchilarning kameralari, Bluetooth chiplari yoki audio mikrosxemalari o&#39;rnatilgan bo&#39;ladi.</p><ul><li><strong>HAL vazifasi:</strong> Apparat qismining o&#39;ziga xos xususiyatlarini yuqori qatlamdagi Java kodidan yashirish va standart C/C++ interfeysini taqdim etish.</li><li>Natijada, dasturchi kamera uchun bitta umumiy Camera API kodini yozadi, HAL esa uni Samsung, Sony yoki Xiaomi sensoriga to&#39;g&#39;ri o&#39;tkazib beradi.</li></ul><h3 id="_3-4-3-qatlam-android-runtime-art-va-native-kutubxonalar" tabindex="-1">3.4. 3-qatlam: Android Runtime (ART) va Native kutubxonalar <a class="header-anchor" href="#_3-4-3-qatlam-android-runtime-art-va-native-kutubxonalar" aria-label="Permalink to &quot;3.4. 3-qatlam: Android Runtime (ART) va Native kutubxonalar&quot;">​</a></h3><ul><li><strong>Native C/C++ kutubxonalari:</strong><ul><li><code>libc</code> (standart C tizimli kutubxonasi);</li><li><code>Media Framework</code> (audio va video formatlarni dekodlash va ijro etish);</li><li><code>Surface Manager</code> (turli ilovalardan keluvchi 2D va 3D grafika qatlamlarini ekranda birlashtiruvchi);</li><li><code>SQLite</code> (engil relyatsion ma&#39;lumotlar bazasi dvigateli);</li><li><code>WebKit / Chromium</code> (veb sahifalarni ko&#39;rsatish dvigateli).</li></ul></li><li><strong>Dalvik vs Android Runtime (ART):</strong><ul><li><strong>Dalvik Virtual Machine (DVM):</strong> Android 4.4 gacha ishlatilgan. Dastur kodi <code>.dex</code> (Dalvik Executable) baytkodiga aylanadi va ilova ochilganda <strong>JIT (Just-in-Time)</strong> usulida mashina kodiga o&#39;giriladi (sekinroq ochilar edi).</li><li><strong>ART (Android Runtime):</strong> Android 5.0 dan boshlab kiritilgan. <strong>AOT (Ahead-of-Time)</strong> kompilyatsiyasi orqali ilova o&#39;rnatilayotgan paytda mashina kodiga kompilyatsiya qilinadi. Natijada ilovalar darhol, silliq va batareyani tejagan holda ishga tushadi.</li></ul></li></ul><h3 id="_3-5-4-qatlam-java-api-framework" tabindex="-1">3.5. 4-qatlam: Java API Framework <a class="header-anchor" href="#_3-5-4-qatlam-java-api-framework" aria-label="Permalink to &quot;3.5. 4-qatlam: Java API Framework&quot;">​</a></h3><p>Dasturchilar Android ilovalari yozishda to&#39;g&#39;ridan-to&#39;g&#39;ri foydalanadigan barcha asosiy tayyor xizmatlar:</p><ul><li><strong>Activity Manager:</strong> Ilovalarning hayotiy sikli (Lifecycle) va orqaga qaytish steki (Backstack) ni boshqaradi;</li><li><strong>View System:</strong> Tugmalar, matnlar, rasmlar, ro&#39;yxatlar, gridlar va oynalarni chizuvchi komponentlar;</li><li><strong>Notification Manager:</strong> Foydalanuvchiga yuqori paneldan bildirishnoma ko&#39;rsatish;</li><li><strong>Content Providers:</strong> Ilovalar o&#39;rtasida ma&#39;lumot almashish (masalan, kontaktlar bazasidan raqam olish);</li><li><strong>Resource Manager:</strong> XML maketlar, matnlar, rasmlar va ranglarni boshqaruvchi xizmat.</li></ul><h3 id="_3-6-5-qatlam-applications-ilovalar-qatlami" tabindex="-1">3.6. 5-qatlam: Applications (Ilovalar qatlami) <a class="header-anchor" href="#_3-6-5-qatlam-applications-ilovalar-qatlami" aria-label="Permalink to &quot;3.6. 5-qatlam: Applications (Ilovalar qatlami)&quot;">​</a></h3><p>Foydalanuvchi ko&#39;radigan barcha dasturlar:</p><ul><li><strong>Tizimli ilovalar (System Apps):</strong> Telefon (Dialer), Kontaktlar, Soat, Kamera, Sozlamalar;</li><li><strong>Foydalanuvchi ilovalari (User Apps):</strong> Telegram, Click, Payme, o&#39;yinlar va biz yaratadigan dasturlar.</li></ul><h3 id="_3-7-ma-lumotlarni-saqlash-texnologiyalari" tabindex="-1">3.7. Ma&#39;lumotlarni saqlash texnologiyalari <a class="header-anchor" href="#_3-7-ma-lumotlarni-saqlash-texnologiyalari" aria-label="Permalink to &quot;3.7. Ma&#39;lumotlarni saqlash texnologiyalari&quot;">​</a></h3><p>Ilovalar ma&#39;lumotlarini qayerda saqlaydi?</p><ol><li><strong>SharedPreferences / DataStore:</strong> Kichik sozlamalar (foydalanuvchi tili, tungi rejim, login holati) kalit-qiymat (Key-Value) juftligida saqlanadi.</li><li><strong>SQLite va Room:</strong> Murakkab relyatsion ma&#39;lumotlar, jadvallar (masalan, mahsulotlar katalogi, xabarlar tarixi). Room — SQLite ustiga qurilgan qulay va xavfsiz Google kutubxonasidir.</li><li><strong>Bulutli bazalar (Firebase Realtime DB / Cloud Firestore):</strong> Internet orqali real vaqtda sinxronlashuvchi online bazalar.</li></ol><hr>`,21))]),i("div",y,[i("h2",p,[l(t,{name:"file-text"}),a[9]||(a[9]=n(" 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari","aria-label":'Permalink to "<Icon name="file-text" /> 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari"'},"​",-1))]),a[11]||(a[11]=r('<h3 id="_1-topshiriq-android-arxitekturasi-qatlamlari-matritsasi-oson" tabindex="-1">1-topshiriq. Android arxitekturasi qatlamlari matritsasi (Oson) <a class="header-anchor" href="#_1-topshiriq-android-arxitekturasi-qatlamlari-matritsasi-oson" aria-label="Permalink to &quot;1-topshiriq. Android arxitekturasi qatlamlari matritsasi (Oson)&quot;">​</a></h3><p><strong>Topshiriq:</strong> 5 ta arxitektura qatlamini pastdan yuqoriga qarab jadvalga joylashtiring va har bir qatlamga bittadan aniq misol yozing.</p><p><strong>Yechim:</strong></p><table tabindex="0"><thead><tr><th>Qatlam tartibi</th><th>Qatlam nomi</th><th>Misol / Komponent</th></tr></thead><tbody><tr><td>5 (Yuqori)</td><td>Applications</td><td>Telegram, Sozlamalar ilovasi</td></tr><tr><td>4</td><td>Java API Framework</td><td>Activity Manager, Notification Manager</td></tr><tr><td>3</td><td>Runtime &amp; Libraries</td><td>ART (Android Runtime), SQLite, Media Framework</td></tr><tr><td>2</td><td>HAL</td><td>Camera HAL, Audio HAL</td></tr><tr><td>1 (Quyi)</td><td>Linux Kernel</td><td>Bluetooth drayveri, Process Scheduler</td></tr></tbody></table><h3 id="_2-topshiriq-dvm-va-art-taqqoslash-tahlili-o-rta" tabindex="-1">2-topshiriq. DVM va ART taqqoslash tahlili (O&#39;rta) <a class="header-anchor" href="#_2-topshiriq-dvm-va-art-taqqoslash-tahlili-o-rta" aria-label="Permalink to &quot;2-topshiriq. DVM va ART taqqoslash tahlili (O&#39;rta)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Dalvik Virtual Machine (DVM) va Android Runtime (ART) o&#39;rtasidagi farqni JIT va AOT tushunchalari asosida taqqoslang. Nega zamonaviy smartfonlar faqat ART&#39;dan foydalanadi?</p><p><strong>Yechim:</strong></p><ul><li><strong>Dalvik (JIT — Just-in-Time):</strong> Ilova kodini har safar ishga tushganda yoki funksiya chaqirilganda bosqichma-bosqich mashina tiliga o&#39;giradi. Bu protsessorga har safar ortiqcha yuk beradi va ilova sekinroq ochiladi.</li><li><strong>ART (AOT — Ahead-of-Time):</strong> Ilova o&#39;rnatilayotganda kodi oldindan to&#39;liq mashina tiliga kompilyatsiya qilinadi. Natijada ilova bir zumda ochiladi, CPU kuchi tejaladi, batareya quvvati 15-20% uzoqroq yetadi. Shuning uchun barcha zamonaviy Android tizimlari ART&#39;dan foydalanadi.</li></ul><h3 id="_3-topshiriq-tizim-xavfsizligi-va-sandbox-tahlili-qiyin" tabindex="-1">3-topshiriq. Tizim xavfsizligi va Sandbox tahlili (Qiyin) <a class="header-anchor" href="#_3-topshiriq-tizim-xavfsizligi-va-sandbox-tahlili-qiyin" aria-label="Permalink to &quot;3-topshiriq. Tizim xavfsizligi va Sandbox tahlili (Qiyin)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Nega bitta ilova (masalan, zararli dastur) boshqa ilovaning (masalan, Click yoki Payme ilovasining) shaxsiy ma&#39;lumotlarini to&#39;g&#39;ridan-to&#39;g&#39;ri o&#39;qiy olmaydi? Linux arxitekturasi bunga qanday to&#39;sqinlik qiladi?</p><p><strong>Yechim:</strong> Android Linuxning ko&#39;p foydalanuvchili (multi-user) xavfsizlik modelidan foydalanadi:</p><ol><li>Har bir o&#39;rnatilgan ilovaga operatsion tizim tomonidan alohida virtual foydalanuvchi ID (UID) belgilanadi (masalan, <code>u0_a125</code>).</li><li>Har bir ilova alohida izolyatsiyalangan Linux jarayonida (Process) ishlaydi.</li><li>Linux fayl tizimida ilovaning shaxsiy papkasi (<code>/data/data/com.example.app/</code>) faqat o&#39;sha ilovaning UID&#39;si uchungina ruxsat etiladi (chmod 700 / 750).</li><li>Boshqa ilovaning UID&#39;si boshqa bo&#39;lgani sababli, operatsion tizim darajasida «Permission Denied» (Ruxsat yo&#39;q) xatosi yuzaga keladi. Bu model «Application Sandbox» (ilova qumqutisi) deb ataladi.</li></ol><hr>',13))]),i("div",b,[i("h2",c,[l(t,{name:"file-text"}),a[12]||(a[12]=n(" 5. Tezkor savol-javob (Blits-savollar) ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-savol-javob-blits-savollar","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor savol-javob (Blits-savollar)"'},"​",-1))]),a[14]||(a[14]=r("<ol><li><strong>Android arxitekturasining eng poydevor qatlami nima?</strong><br><em>Javob:</em> Linux Kernel (Linux yadrosi).</li><li><strong>HAL nimani anglatadi va uning vazifasi nima?</strong><br><em>Javob:</em> Hardware Abstraction Layer — apparat ta&#39;minotining abstraksiya qatlami bo&#39;lib, Java kodini turli kameralar va chiplar bilan standart interfeys orqali bog&#39;laydi.</li><li><strong>Androidda kompilyatsiya qilingan Java/Kotlin kodi qanday fayl formatiga aylanadi?</strong><br><em>Javob:</em> <code>.dex</code> (Dalvik Executable) formatiga.</li><li><strong>Ilovalarning hayotiy siklini qaysi Framework komponenti boshqaradi?</strong><br><em>Javob:</em> Activity Manager.</li><li><strong>Kichik foydalanuvchi sozlamalarini saqlash uchun qaysi texnologiya ishlatiladi?</strong><br><em>Javob:</em> SharedPreferences yoki zamonaviy DataStore.</li></ol><hr>",2))]),i("div",x,[i("h2",f,[l(t,{name:"file-text"}),a[15]||(a[15]=n(" 6. Mentor uchun amaliy tavsiyalar ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-mentor-uchun-amaliy-tavsiyalar","aria-label":'Permalink to "<Icon name="file-text" /> 6. Mentor uchun amaliy tavsiyalar"'},"​",-1))]),a[17]||(a[17]=i("ul",null,[i("li",null,"O'quvchilarga arxitekturani «ko'p qavatli bino» o'xshatishi orqali tushuntiring: 1-qavat — mustahkam poydevor (Linux), 2-qavat — santexnika va simlar (HAL), 3-qavat — elektr motorlar (ART va kutubxonalar), 4-qavat — xonalar karkasi (Framework), 5-qavat — mebel va yashovchilar (Ilovalar)."),i("li",null,"Doskada yoki ekranda Linux UID izolyatsiyasini misol qilib ko'rsating, bu ularda kiberxavfsizlikka oid dastlabki to'g'ri tasavvurni shakllantiradi.")],-1))])])}const S=o(m,[["render",A]]);export{I as __pageData,S as default};
